(()=>{const q=new URLSearchParams(location.search).get('q')?.trim().toLowerCase();const host=document.querySelector('#search-results');if(!host)return;const index=[...document.querySelectorAll('a[href]')].map(a=>({title:a.textContent.trim(),href:a.href,text:(a.textContent+' '+a.getAttribute('href')).toLowerCase()})).filter(x=>x.title);if(!q){host.innerHTML='';return}const results=index.filter(x=>x.text.includes(q)).slice(0,12);host.innerHTML=results.length?results.map(x=>'<article class="search-hit"><a href="'+x.href+'">'+x.title+'</a></article>').join(''):'<p>'+host.dataset.empty+'</p>'})();